<script setup lang="ts">import {computed,ref} from "vue";import {Plus,Landmark} from "lucide-vue-next";import AppShell from "@/components/zs/AppShell.vue";import PageHeader from "@/components/zs/PageHeader.vue";import Panel from "@/components/zs/Panel.vue";import StatCard from "@/components/zs/StatCard.vue";import DataTable,{type Column} from "@/components/zs/DataTable.vue";import StatusBadge from "@/components/zs/StatusBadge.vue";import SidePanel from "@/components/zs/SidePanel.vue";import Field from "@/components/zs/Field.vue";import ZButton from "@/components/zs/ZButton.vue";import AsyncSection from "@/components/zs/AsyncSection.vue";import {useAsyncData} from "@/composables/useAsyncData";import {useCompanyStore} from "@/stores/company";import {operationsRepository} from "@/services/operations/repository";import {formatMoney} from "@/lib/money";import {showToast} from "@/composables/useToast";import {setPageMeta} from "@/lib/page-meta";import type {BankAccount} from "@/types/operations";setPageMeta("Bank & Cash Accounts","Manage company bank, cash, wallet and processor accounts.");const c=useCompanyStore(),state=useAsyncData(()=>operationsRepository.bankAccounts(c.activeCompanyId),{watch:[()=>c.activeCompanyId]}),open=ref(false),name=ref(""),institution=ref("");const rows=computed(()=>state.data.value??[]),balance=computed(()=>rows.value.reduce((s,x)=>s+x.balance,0));const columns:Column[]=[{key:"account",header:"Account"},{key:"type",header:"Type"},{key:"currency",header:"Currency"},{key:"balance",header:"Book balance",align:"right",class:"num"},{key:"available",header:"Available",align:"right",class:"num"},{key:"status",header:"Status"}];function save(){open.value=false;showToast('Account ready for review','Preview data is not sent until the banking API is connected.','info')}</script><template><AppShell><PageHeader title="Bank & Cash Accounts" description="Balances and account connections scoped to the active company"><template #actions><ZButton @click="open=true"><Plus class="size-4"/>Add account</ZButton></template></PageHeader><div class="mb-4 grid gap-3 sm:grid-cols-3"><StatCard label="Total book balance" :value="formatMoney(balance)" tone="brand"/><StatCard label="Available funds" :value="formatMoney(rows.reduce((s,x)=>s+x.available,0))" tone="success"/><StatCard label="Connected accounts" :value="String(rows.filter(x=>x.status==='active').length)"/></div><Panel><AsyncSection :loading="state.loading.value" :error="state.error.value" :empty="state.isEmpty.value" @retry="state.refresh"><DataTable :columns="columns" :rows="rows" :min-width="850"><template #account="{row}:{row:BankAccount}"><div class="flex items-center gap-2"><span class="grid size-8 place-items-center rounded-md bg-primary-subtle text-primary-subtle-fg"><Landmark class="size-4"/></span><div><p class="font-medium text-content">{{row.name}}</p><p class="text-2xs text-content-muted">{{row.institution}} · {{row.masked_number}} <span v-if="row.is_default">· Default</span></p></div></div></template><template #type="{row}"><span class="capitalize">{{row.type}}</span></template><template #currency="{row}">{{row.currency}}</template><template #balance="{row}">{{formatMoney(row.balance)}}</template><template #available="{row}">{{formatMoney(row.available)}}</template><template #status="{row}"><StatusBadge :status="row.status"/></template></DataTable></AsyncSection></Panel><SidePanel :open="open" title="Add bank or cash account" description="Connection credentials are handled only by the future secure backend." @close="open=false"><form class="space-y-4" @submit.prevent="save"><Field v-model="name" label="Account name" required/><Field v-model="institution" label="Institution" required/><label class="block"><span class="label-caps">Account type</span><select class="field mt-1.5 w-full"><option>Bank</option><option>Cash</option><option>Wallet</option><option>Payment processor</option></select></label><ZButton type="submit">Save account</ZButton></form></SidePanel></AppShell></template>